from png_probe import decode
w,h,nch,px = decode('_test_t0.svg.png')
S=2
def get(x,y):
    sx,sy=min(int(x/S),w-1),min(int(y/S),h-1)
    o=(sy*w+sx)*nch
    return tuple(px[o:o+3])

def cls(c):
    r,g,b=c
    if r>200 and g>240 and b>250: return '.'          # light sky
    if b>180 and b>r+30: return ':'                   # sky blue
    if r>230 and g>200 and b<120: return 'Y'          # yellow (sun/hub/dash)
    if r>230 and g>120 and g<210 and b<110: return 'O' # orange (beak/legs)
    if r>220 and g<110 and b<110: return 'R'          # red (helmet/deck)
    if r<80 and g<80 and b<90: return '#'             # dark (outlines/wheels)
    if r>235 and g>230: return 'w'                    # white (body/cloud)
    if g>170 and r>140 and b>120 and g>r+20: return 'g' # green hills
    if abs(r-g)<25 and abs(g-b)<25: return '='        # gray road
    if r>230 and g>170 and b<150: return 'o'          # light orange pouch
    return '?'

for row in range(0,1024,16):
    line=''.join(cls(get(x,row)) for x in range(0,1024,16))
    print(f"{row:4d} {line}")
EOF

